// لماذا نستخدم Option<Box<Tree>>؟ لتمثيل غياب العقدة دون مؤشرات خام
#[derive(Default)]
struct Tree {
    val: i32,
    left: Option<Box<Tree>>,
    right: Option<Box<Tree>>,
}

impl Tree {
    fn insert(&mut self, v: i32) {
        if v < self.val {
            match self.left {
                Some(ref mut l) => l.insert(v),
                None => self.left = Some(Box::new(Tree { val: v, ..Default::default() })),
            }
        } else if v > self.val {
            match self.right {
                Some(ref mut r) => r.insert(v),
                None => self.right = Some(Box::new(Tree { val: v, ..Default::default() })),
            }
        }
    }

    fn inorder(&self) {
        if let Some(ref l) = self.left { l.inorder(); }
        println!("{}", self.val);
        if let Some(ref r) = self.right { r.inorder(); }
    }
}

fn main() {
    let mut root = Tree { val: 50, ..Default::default() };
    for &v in &[30, 70, 20, 40, 60, 80] {
        root.insert(v);
    }
    // الاجتياز بالترتيب يعطي القيم مرتبة تصاعديًا
    root.inorder();
}

