fn main() {
    let mut cache: HashMap<u64, u64> = HashMap::new();
    // مُغلِّقٌ يحسبُ المضروبَ مع تذكيرٍ تلقائيٍّ للقيمِ المحسوبةِ سابقاً
    let mut factorial = |n: u64| -> u64 {
        if let Some(&v) = cache.get(&n) { return v; }
        let result = (1..=n).product();
        cache.insert(n, result);
        result
    };
    println!("5! = {}", factorial(5));
    println!("5! again = {}", factorial(5)); // من الكاشِ مباشرةً
}

