fn fib(n: u32) -> u64 {
    // نستخدم مصفوفة لتخزين النتائج السابقة
    let mut dp = vec![0u64; (n + 1) as usize];
    dp[1] = 1;
    for i in 2..=n as usize {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    dp[n as usize]
}

