fn knapsack(capacity: usize, weights: &[usize], values: &[usize]) -> usize {
    let n = weights.len();
    let mut dp = vec![vec![0; capacity + 1]; n + 1];
    for i in 1..=n {
        for w in 1..=capacity {
            if weights[i - 1] <= w {
                dp[i][w] = dp[i - 1][w].max(dp[i - 1][w - weights[i - 1]] + values[i - 1]);
            } else {
                dp[i][w] = dp[i - 1][w];
            }
        }
    }
    dp[n][capacity]
}

fn main() {
    let weights = [2, 3, 4, 5];
    let values = [3, 4, 5, 6];
    let capacity = 5;
    println!("Max value: {}", knapsack(capacity, &weights, &values));
}

