// لماذا نستخدم Box؟ لأن العقدة تشير إلى التالية ديناميكيًا
struct Node {
    val: i32,
    next: Option<Box<Node>>,
}

struct Stack {
    head: Option<Box<Node>>,
}

impl Stack {
    fn new() -> Self {
        Stack { head: None }
    }

    fn push(&mut self, v: i32) {
        let n = Node { val: v, next: self.head.take() };
        self.head = Some(Box::new(n));
    }

    fn pop(&mut self) -> Option<i32> {
        self.head.take().map(|node| {
            self.head = node.next;
            node.val
        })
    }
}

fn main() {
    let mut s = Stack::new();
    s.push(10);
    s.push(20);
    s.push(30);
    // الترتيب العكسي يثبت خاصية LIFO
    while let Some(v) = s.pop() {
        println!("{}", v);
    }
}

