fn main() {
    let rows = 6;
    // مصفوفة مثلثية لتخزين القيم
    let mut triangle: Vec<Vec<u64>> = Vec::with_capacity(rows);
    for i in 0..rows {
        let mut row = vec![1; i + 1]; // كل صف يبدأ وينتهي بـ 1
        // القيم الداخلية هي مجموع القيمتين فوقها
        for j in 1..i {
