        }
        triangle.push(row);
    }
    // طباعة المثلث بشكل هرمي
    for (i, row) in triangle.iter().enumerate() {
        let spaces = " ".repeat((rows - i - 1) * 2);
        let nums: Vec<String> = row.iter().map(|x| x.to_string()).collect();
        println!("{}{}", spaces, nums.join(" "));
    }
}

