fn is_perfect(n: u64) -> bool {
    // نجمع القواسم حتى n/2 لأن أكبر قاسم حقيقي هو n/2
    let sum: u64 = (1..=n/2).filter(|&d| n % d == 0).sum();
    sum == n
}

