    if vowels.contains(&first) {
        // إذا بدأت بحرف علة نضيف "way"
        format!("{}-way", word)
    } else {
        // ننقل الحرف الأول إلى النهاية ونضيف "ay"
        let rest = &word[1..];
        format!("{}-{}ay", rest, first)
    }
}

