fn prime_factors(mut n: u64) -> Vec<u64> {
    let mut factors = Vec::new();
    // نعالج العامل 2 أولاً لأنه الزوجي الوحيد
    while n % 2 == 0 {
        factors.push(2);
        n /= 2;
    }
    // نبدأ من 3 ونزيد بمقدار 2 لتجنب الأعداد الزوجية
    let mut i = 3;
    while i * i <= n {
        while n % i == 0 {
            factors.push(i);
            n /= i;
        }
        i += 2;
    }
    // إذا بقي n أكبر من 1 فهو عدد أولي
    if n > 1 {
        factors.push(n);
    }
    factors
}

fn main() {
    let n = 84;
    let factors = prime_factors(n);
    println!("Prime factors of {}: {:?}", n, factors);
}

fn main() {
    let limit = 30;
    let mut is_prime = vec![true; limit + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    // نبدأ من 2 ونعلّم مضاعفاته كأعداد غير أولية
    let mut p = 2;
    while p * p <= limit {
        if is_prime[p] {
            let mut multiple = p * p;
            while multiple <= limit {
                is_prime[multiple] = false;
                multiple += p;
            }
        }
        p += 1;
    }

    let primes: Vec<usize> = (2..=limit).filter(|&i| is_prime[i]).collect();
    println!("Primes up to {}: {:?}", limit, primes);
}

