fn partition(arr: &mut [i32]) -> usize {
    let pivot = arr[arr.len() - 1];
    let mut i = 0;
    for j in 0..arr.len() - 1 {
        if arr[j] <= pivot {
            arr.swap(i, j);
            i += 1;
        }
    }
    arr.swap(i, arr.len() - 1);
    i
}

fn quick_sort(arr: &mut [i32]) {
    if arr.len() <= 1 {
        return;
    }
    let p = partition(arr);
    quick_sort(&mut arr[..p]);
    quick_sort(&mut arr[p + 1..]);
}

fn main() {
    let mut arr = [10, 7, 8, 9, 1, 5];
