struct BankAccount {
    // الحقلُ خاصٌّ لا يُرى خارجَ الصندوق
    balance: f64,
}

impl BankAccount {
    // مُنشئٌ يضبطُ الرصيدَ الابتدائي
    fn new(initial: f64) -> Self {
        BankAccount { balance: initial }
    }

    // مُحدِّدُ قراءةٍ (getter)
    fn balance(&self) -> f64 {
        self.balance
    }

    // إيداعٌ يتحقّقُ من القيمةِ الموجبة
    fn deposit(&mut self, amount: f64) {
        if amount > 0.0 {
            self.balance += amount;
        }
    }

    // سحبٌ يمنعُ تجاوزَ الرصيد
    fn withdraw(&mut self, amount: f64) -> bool {
        if amount > 0.0 && amount <= self.balance {
            self.balance -= amount;
            true
        } else {
            false
        }
    }
}

fn main() {
    let mut acc = BankAccount::new(100.0);
    acc.deposit(50.0);
    let ok = acc.withdraw(30.0);
    println!("Withdraw ok: {}", ok);
    println!("Balance: {}", acc.balance());
}

fn hanoi(n: u32, from: char, to: char, aux: char) {
    if n == 1 {
        println!("Move disk 1 from {} to {}", from, to);
    } else {
        hanoi(n - 1, from, aux, to);
        println!("Move disk {} from {} to {}", n, from, to);
        hanoi(n - 1, aux, to, from);
    }
}

